package dev.anydisplay.client.protocol

import org.json.JSONObject
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Test
import java.io.File

/** Reproduces every value in tools/vectors.json (generated by `anydisplay_ref.py vectors`). */
class VectorsTest {
    companion object {
        val v: JSONObject by lazy {
            val path = System.getProperty("anydisplay.vectors") ?: "../../tools/vectors.json"
            JSONObject(File(path).readText())
        }

        fun hex(key: String, o: JSONObject = v) = o.getString(key).hexToBytes()

        val clientKeys by lazy { Crypto.keyPairFromRaw(hex("client_private"), hex("client_pub")) }
        val hostKeys by lazy { Crypto.keyPairFromRaw(hex("host_private"), hex("host_pub")) }
        val deviceId = ByteArray(16) { (0xA0 + it).toByte() }
        val hostId = ByteArray(16) { (0xB0 + it).toByte() }
    }

    @Test
    fun publicKeysRoundTrip() {
        assertArrayEquals(hex("client_pub"), Crypto.encodePublicKey(clientKeys.public))
        assertArrayEquals(hex("host_pub"), Crypto.encodePublicKey(hostKeys.public))
    }

    @Test
    fun helloBodies() {
        val nonce = hex("client_nonce")
        assertArrayEquals(ByteArray(32) { it.toByte() }, nonce)
        val helloC = HelloC(deviceId, "Phone", 1, 1, hex("client_pub"), Crypto.sha256(nonce)).encode()
        assertArrayEquals(hex("hello_c_body"), helloC)

        val h = HelloH.decode(hex("hello_h_body"))!!
        assertArrayEquals(hostId, h.hostId)
        assertEquals("Mac", h.hostName)
        assertEquals("macOS", h.hostOs)
        assertEquals(1, h.authMode)
        assertArrayEquals(hex("host_pub"), h.hostPub)
        assertArrayEquals(hex("host_nonce"), h.hostNonce)
        assertArrayEquals(nonce, hex("reveal_body"))
    }

    @Test
    fun transcriptSasAndEcdh() {
        val t = Crypto.transcript(hex("hello_c_body"), hex("hello_h_body"), hex("reveal_body"))
        assertArrayEquals(hex("transcript"), t)
        assertEquals(v.getString("sas"), Crypto.formatSas(Crypto.sas(t)))
        assertArrayEquals(hex("ecdh_z"), Crypto.ecdh(clientKeys.private, hostKeys.public))
        assertArrayEquals(hex("ecdh_z"), Crypto.ecdh(hostKeys.private, clientKeys.public))
    }

    private fun checkMode(name: String) {
        val m = v.getJSONObject(name)
        val t = hex("transcript")
        val keys = Crypto.keySchedule(hex("ecdh_z"), hex("psk", m), t)
        assertArrayEquals(hex("k_h2c", m), keys.kH2c)
        assertArrayEquals(hex("k_c2h", m), keys.kC2h)
        assertArrayEquals(hex("k_confirm", m), keys.kConfirm)
        assertArrayEquals(hex("auth_h", m), Crypto.confirmMac(keys.kConfirm, Crypto.HOST_LABEL, t))
        assertArrayEquals(hex("auth_c", m), Crypto.confirmMac(keys.kConfirm, Crypto.CLIENT_LABEL, t))

        val ping = hex("ping_plaintext_body")
        assertArrayEquals(ping, Bodies.ping(7, 123456789))
        val enc = FrameCipher(keys.kH2c).encrypt(Proto.CH_CONTROL, Proto.PING, ping)
        assertArrayEquals(hex("encrypted_ping_h2c_seq0", m), enc)
        assertArrayEquals(ping, FrameCipher(keys.kH2c).decrypt(Proto.CH_CONTROL, Proto.PING, enc))
    }

    @Test fun mode1Keys() = checkMode("mode1")

    @Test fun mode2Keys() = checkMode("mode2")

    @Test(expected = Exception::class)
    fun tamperedFrameFailsAuthentication() {
        val keys = Crypto.keySchedule(hex("ecdh_z"), ByteArray(0), hex("transcript"))
        val enc = hex("encrypted_ping_h2c_seq0", v.getJSONObject("mode1"))
        // Same bytes under a different (channel, type) AAD must not authenticate.
        FrameCipher(keys.kH2c).decrypt(Proto.CH_CONTROL, Proto.PONG, enc)
    }

    @Test
    fun hkdfRfc5869Case1() {
        val okm = Crypto.hkdfSha256(
            "000102030405060708090a0b0c".hexToBytes(),
            "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b".hexToBytes(),
            "f0f1f2f3f4f5f6f7f8f9".hexToBytes(), 42,
        )
        assertEquals("3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865", okm.toHex())
    }

    @Test(expected = ProtocolException::class)
    fun rejectsPointOffCurve() {
        val bad = hex("host_pub").also { it[64] = (it[64].toInt() xor 1).toByte() }
        Crypto.decodePublicKey(bad)
    }
}
